// frontend/src/auth/Signup.jsx
import React, { useState, useContext, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "./AuthContext";

export default function Signup() {
  const { saveToken } = useContext(AuthContext);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();
  const canvasRef = React.useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    
    const ctx = canvas.getContext('2d');
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    class AuroraWave {
      constructor(offset) {
        this.offset = offset;
        this.time = Math.random() * 100;
        this.color = [
          [100, 255, 180],
          [157, 217, 255],
          [200, 100, 255]
        ][Math.floor(Math.random() * 3)];
      }
      
      draw() {
        ctx.beginPath();
        ctx.moveTo(0, canvas.height / 2);
        
        for (let x = 0; x < canvas.width; x += 5) {
          const y = canvas.height / 3 + 
                   Math.sin(x * 0.003 + this.time) * 100 +
                   Math.sin(x * 0.001 + this.time * 0.5) * 50 +
                   this.offset;
          
          if (x === 0) {
            ctx.moveTo(x, y);
          } else {
            ctx.lineTo(x, y);
          }
        }
        
        ctx.lineTo(canvas.width, canvas.height);
        ctx.lineTo(0, canvas.height);
        ctx.closePath();
        
        const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
        gradient.addColorStop(0, `rgba(${this.color[0]}, ${this.color[1]}, ${this.color[2]}, 0.3)`);
        gradient.addColorStop(1, 'transparent');
        
        ctx.fillStyle = gradient;
        ctx.fill();
        
        this.time += 0.01;
      }
    }
    
    const waves = [
      new AuroraWave(-50),
      new AuroraWave(0),
      new AuroraWave(50),
      new AuroraWave(100)
    ];
    
    const handleResize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', handleResize);
    
    function animateAurora() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      waves.forEach(wave => wave.draw());
      requestAnimationFrame(animateAurora);
    }
    
    animateAurora();
    
    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  const handleSignup = async () => {
    if (!name || !email || !password) {
      alert("Please fill all fields");
      return;
    }
    if (password !== confirm) {
      alert("Passwords do not match");
      return;
    }

    setIsLoading(true);
    try {
      const res = await fetch("http://127.0.0.1:8000/auth/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, email, password }),
      });

      const data = await res.json();

      if (!res.ok) {
        alert(data.detail || "Signup failed");
        return;
      }

      saveToken(data.token, data.user);
      navigate("/join");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div style={{
      minHeight: "100vh",
      width: "100vw",
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      background: "linear-gradient(to bottom, #001428 0%, #0a0e27 100%)",
      padding: "20px",
      fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
      position: "relative",
      overflow: "hidden",
      margin: 0
    }}>
      <div style={{
        position: "fixed",
        width: "100%",
        height: "100%",
        top: 0,
        left: 0,
        pointerEvents: "none"
      }}>
        {Array.from({ length: 200 }).map((_, i) => (
          <div
            key={i}
            style={{
              position: "absolute",
              width: "2px",
              height: "2px",
              background: "white",
              borderRadius: "50%",
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
              opacity: Math.random() * 0.7 + 0.3,
              animation: `twinkle ${2 + Math.random() * 3}s infinite ${Math.random() * 3}s`
            }}
          />
        ))}
      </div>

      <canvas
        ref={canvasRef}
        style={{
          position: "fixed",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
          opacity: 0.8
        }}
      />

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes twinkle {
          0%, 100% { opacity: 0.3; }
          50% { opacity: 1; }
        }
        @keyframes auroraGlow {
          0%, 100% { box-shadow: 0 0 20px rgba(100, 255, 180, 0.3); }
          50% { box-shadow: 0 0 40px rgba(157, 217, 255, 0.5); }
        }
        input:focus {
          outline: none;
          border-color: #64ffb4;
          box-shadow: 0 0 10px rgba(100, 255, 180, 0.5);
        }
        .hover-lift {
          transition: all 0.3s ease;
        }
        .hover-lift:hover {
          transform: translateY(-4px);
          box-shadow: 0 0 30px rgba(100, 255, 180, 0.4), 0 8px 32px rgba(157, 217, 255, 0.3);
        }
        button:disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }
      `}</style>

      <div style={{
        width: "480px",
        background: "rgba(0, 20, 40, 0.7)",
        backdropFilter: "blur(20px)",
        padding: "48px",
        borderRadius: "20px",
        boxShadow: "0 8px 32px rgba(100, 255, 180, 0.2)",
        border: "1px solid rgba(100, 255, 180, 0.3)",
        animation: "fadeIn 0.5s ease-out, auroraGlow 4s ease-in-out infinite",
        position: "relative",
        zIndex: 10
      }}
      className="hover-lift">
        
        <div style={{ textAlign: "center", marginBottom: "32px" }}>
          <h1 style={{
            fontSize: "32px",
            fontWeight: "700",
            color: "#64ffb4",
            marginBottom: "8px",
            textShadow: "0 0 20px rgba(100, 255, 180, 0.8)"
          }}>
            Create Account
          </h1>
          <p style={{
            color: "#9dd9ff",
            fontSize: "15px"
          }}>
            Sign up to get started
          </p>
        </div>

        <div style={{ marginBottom: "20px" }}>
          <label style={{
            display: "block",
            fontWeight: "600",
            fontSize: "14px",
            color: "#64ffb4",
            marginBottom: "8px"
          }}>
            Full Name
          </label>
          <input
            type="text"
            placeholder="Enter your full name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            style={{
              width: "100%",
              padding: "12px 16px",
              borderRadius: "10px",
              border: "1px solid rgba(100, 255, 180, 0.3)",
              fontSize: "15px",
              transition: "all 0.3s ease",
              backgroundColor: "rgba(0, 20, 40, 0.5)",
              color: "#fff"
            }}
          />
        </div>

        <div style={{ marginBottom: "20px" }}>
          <label style={{
            display: "block",
            fontWeight: "600",
            fontSize: "14px",
            color: "#64ffb4",
            marginBottom: "8px"
          }}>
            Email address
          </label>
          <input
            type="email"
            placeholder="Enter your email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={{
              width: "100%",
              padding: "12px 16px",
              borderRadius: "10px",
              border: "1px solid rgba(100, 255, 180, 0.3)",
              fontSize: "15px",
              transition: "all 0.3s ease",
              backgroundColor: "rgba(0, 20, 40, 0.5)",
              color: "#fff"
            }}
          />
        </div>

        <div style={{ marginBottom: "20px" }}>
          <label style={{
            display: "block",
            fontWeight: "600",
            fontSize: "14px",
            color: "#64ffb4",
            marginBottom: "8px"
          }}>
            Password
          </label>
          <input
            type="password"
            placeholder="Create a password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{
              width: "100%",
              padding: "12px 16px",
              borderRadius: "10px",
              border: "1px solid rgba(100, 255, 180, 0.3)",
              fontSize: "15px",
              transition: "all 0.3s ease",
              backgroundColor: "rgba(0, 20, 40, 0.5)",
              color: "#fff"
            }}
          />
        </div>

        <div style={{ marginBottom: "24px" }}>
          <label style={{
            display: "block",
            fontWeight: "600",
            fontSize: "14px",
            color: "#64ffb4",
            marginBottom: "8px"
          }}>
            Confirm Password
          </label>
          <input
            type="password"
            placeholder="Retype your password"
            value={confirm}
            onChange={(e) => setConfirm(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && handleSignup()}
            style={{
              width: "100%",
              padding: "12px 16px",
              borderRadius: "10px",
              border: "1px solid rgba(100, 255, 180, 0.3)",
              fontSize: "15px",
              transition: "all 0.3s ease",
              backgroundColor: "rgba(0, 20, 40, 0.5)",
              color: "#fff"
            }}
          />
        </div>

        <button
          onClick={handleSignup}
          disabled={isLoading}
          style={{
            width: "100%",
            background: "linear-gradient(135deg, #64ffb4 0%, #9dd9ff 100%)",
            color: "#001428",
            padding: "14px",
            borderRadius: "10px",
            fontSize: "16px",
            fontWeight: "700",
            border: "none",
            cursor: "pointer",
            transition: "all 0.3s ease",
            boxShadow: "0 4px 20px rgba(100, 255, 180, 0.4)"
          }}
          onMouseOver={(e) => {
            if (!isLoading) {
              e.target.style.transform = "translateY(-2px)";
              e.target.style.boxShadow = "0 6px 30px rgba(100, 255, 180, 0.6)";
            }
          }}
          onMouseOut={(e) => {
            e.target.style.transform = "translateY(0)";
            e.target.style.boxShadow = "0 4px 20px rgba(100, 255, 180, 0.4)";
          }}
        >
          {isLoading ? "Creating account..." : "Create account"}
        </button>

        <div style={{
          textAlign: "center",
          marginTop: "24px",
          fontSize: "14px",
          color: "#ff00ff"
        }}>
          Already have an account?{" "}
          <a
            href="/login"
            style={{
              color: "#00ffff",
              fontWeight: "600",
              textDecoration: "none",
              textShadow: "0 0 5px rgba(0, 255, 255, 0.5)"
            }}
          >
            Sign in here
          </a>
        </div>
      </div>
    </div>
  );
}
